<html lang="en">
<head>
<meta charset="utf-8">
<title>JS Framework Benchmark - Infographic</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg-primary: #0d1117;
    --bg-secondary: #161b22;
    --bg-tertiary: #21262d;
    --border: #30363d;
    --blue: #58a6ff;
    --green: #3fb950;
    --amber: #d29922;
    --orange: #f78166;
    --purple: #a371f7;
    --teal: #39d2c0;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-muted: #6e7681;
  }

  body {
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    display: flex;
    justify-content: center;
    padding: 0;
    background-image:
      radial-gradient(circle, var(--border) 1px, transparent 1px);
    background-size: 24px 24px;
    background-position: 0 0;
  }

  .poster {
    width: 1200px;
    background: var(--bg-primary);
    padding: 48px 56px 40px;
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  /* ── HEADER ── */
  .poster-header {
    text-align: center;
    padding-bottom: 32px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 36px;
  }
  .poster-header .kicker {
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 13px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 12px;
  }
  .poster-header h1 {
    font-size: 42px;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.15;
    color: var(--text-primary);
    margin-bottom: 8px;
  }
  .poster-header h1 .accent { color: var(--blue); }
  .poster-header .subtitle {
    font-size: 18px;
    color: var(--text-secondary);
    font-weight: 400;
    max-width: 700px;
    margin: 0 auto;
    line-height: 1.5;
  }

  /* ── SECTION TITLES ── */
  .section-title {
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 13px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 4px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .section-title::before {
    content: '';
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--blue);
  }

  /* ── INFOG CONTAINERS ── */
  .infog-section {
    padding: 28px 0;
    border-bottom: 1px solid var(--border);
  }
  .infog-section:last-of-type { border-bottom: none; }
  .infog-container {
    width: 100%;
    min-height: 200px;
  }
  .infog-container svg { max-width: 100%; height: auto; }

  /* ── HERO ROW ── */
  .hero-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    padding: 28px 0;
    border-bottom: 1px solid var(--border);
  }
  .hero-card {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px 20px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .hero-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }
  .hero-card:nth-child(1)::before { background: var(--blue); }
  .hero-card:nth-child(2)::before { background: var(--green); }
  .hero-card:nth-child(3)::before { background: var(--purple); }
  .hero-value {
    font-size: 48px;
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1;
    margin-bottom: 6px;
  }
  .hero-card:nth-child(1) .hero-value { color: var(--blue); }
  .hero-card:nth-child(2) .hero-value { color: var(--green); }
  .hero-card:nth-child(3) .hero-value { color: var(--purple); }
  .hero-label {
    font-size: 13px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-secondary);
    margin-bottom: 6px;
  }
  .hero-context {
    font-size: 12px;
    color: var(--text-muted);
    line-height: 1.4;
  }

  /* ── WARNING CALLOUT ── */
  .callout-warn {
    background: rgba(210, 153, 34, 0.08);
    border: 1px solid rgba(210, 153, 34, 0.25);
    border-left: 4px solid var(--amber);
    border-radius: 6px;
    padding: 16px 20px;
    margin: 16px 0;
    display: flex;
    align-items: flex-start;
    gap: 12px;
  }
  .callout-warn .icon { font-size: 20px; flex-shrink: 0; margin-top: 1px; }
  .callout-warn .msg { font-size: 14px; line-height: 1.5; color: var(--text-primary); }
  .callout-warn .msg strong { color: var(--amber); }

  /* ── COVERAGE STATS ── */
  .coverage-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-top: 12px;
  }
  .cov-card {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    gap: 16px;
  }
  .cov-icon {
    width: 44px; height: 44px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
    flex-shrink: 0;
  }
  .cov-icon.mac { background: rgba(88,166,255,0.12); }
  .cov-icon.win { background: rgba(248,129,102,0.12); }
  .cov-info .cov-pct { font-size: 28px; font-weight: 700; letter-spacing: -0.02em; }
  .cov-info .cov-label { font-size: 12px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.06em; }
  .cov-info .cov-detail { font-size: 11px; color: var(--text-muted); margin-top: 2px; }

  /* ── FOOTER ── */
  .poster-footer {
    margin-top: 32px;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .poster-footer .source {
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 11px;
    color: var(--text-muted);
  }
  .poster-footer .source a { color: var(--blue); text-decoration: none; }
  .poster-footer .date {
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 11px;
    color: var(--text-muted);
  }

  /* ── CHROME VERSION GRID ── */
  .chrome-timeline {
    display: grid;
    grid-template-columns: repeat(8, 1fr);
    gap: 8px;
    margin-top: 16px;
  }
  .year-block {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px 10px;
    text-align: center;
  }
  .year-block .yr {
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 15px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 4px;
  }
  .year-block .vers {
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 11px;
    color: var(--text-muted);
    margin-bottom: 6px;
  }
  .year-block .runs {
    font-size: 22px;
    font-weight: 700;
    color: var(--blue);
  }
  .year-block .runs-label {
    font-size: 9px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-muted);
  }
  .year-block.milestone {
    border-color: var(--amber);
    position: relative;
  }
  .year-block.milestone::after {
    content: '⚠ METHODOLOGY CHANGE';
    position: absolute;
    bottom: -20px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: var(--amber);
    white-space: nowrap;
    font-family: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', 'Fira Code', monospace;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- ═══ HEADER ═══ -->
  <header class="poster-header">
    <div class="kicker">Data Report &middot; May 2026</div>
    <h1>JS Framework <span class="accent">Benchmark</span></h1>
    <p class="subtitle">
      A comprehensive overview of the longest-running JavaScript web framework benchmark
      — 60+ official runs tracking browser performance from Chrome 55 through Chrome 146.
    </p>
  </header>

  <!-- ═══ HERO NUMBERS ═══ -->
  <div class="hero-row">
    <div class="hero-card">
      <div class="hero-value">60+</div>
      <div class="hero-label">Official Runs</div>
      <div class="hero-context">Chrome 55 (2017) through Chrome 146 (2026)</div>
    </div>
    <div class="hero-card">
      <div class="hero-value">55 &rarr; 146</div>
      <div class="hero-label">Chrome Versions</div>
      <div class="hero-context">Spanning approximately 8 years of browser releases</div>
    </div>
    <div class="hero-card">
      <div class="hero-value">macOS 95%+</div>
      <div class="hero-label">Primary Platform</div>
      <div class="hero-context">Only 2 out of 60+ runs executed on Windows</div>
    </div>
  </div>

  <!-- ═══ TIMELINE SECTION ═══ -->
  <section class="infog-section">
    <div class="section-title">Benchmark Timeline</div>
    <h2 style="font-size:24px;font-weight:700;letter-spacing:-0.02em;margin-bottom:4px;">Chrome 55 &rarr; Chrome 146</h2>
    <p style="font-size:14px;color:var(--text-secondary);margin-bottom:12px;">Distribution of 60+ official benchmark runs across 8 years, with key Chrome version ranges.</p>

    <div class="chrome-timeline">
      <div class="year-block">
        <div class="yr">2017&ndash;19</div>
        <div class="vers">Chrome 55&ndash;69</div>
        <div class="runs">4</div>
        <div class="runs-label">Runs</div>
      </div>
      <div class="year-block">
        <div class="yr">2020</div>
        <div class="vers">Chrome 83&ndash;87</div>
        <div class="runs">5</div>
        <div class="runs-label">Runs</div>
      </div>
      <div class="year-block">
        <div class="yr">2021</div>
        <div class="vers">Chrome 88&ndash;96</div>
        <div class="runs">9</div>
        <div class="runs-label">Runs</div>
      </div>
      <div class="year-block">
        <div class="yr">2022</div>
        <div class="vers">Chrome 97&ndash;108</div>
        <div class="runs">13</div>
        <div class="runs-label">Runs</div>
      </div>
      <div class="year-block milestone">
        <div class="yr">2023</div>
        <div class="vers">Chrome 109&ndash;120</div>
        <div class="runs">12</div>
        <div class="runs-label">Runs</div>
      </div>
      <div class="year-block">
        <div class="yr">2024</div>
        <div class="vers">Chrome 121&ndash;131</div>
        <div class="runs">12</div>
        <div class="runs-label">Runs</div>
      </div>
      <div class="year-block">
        <div class="yr">2025</div>
        <div class="vers">Chrome 132&ndash;143</div>
        <div class="runs">12</div>
        <div class="runs-label">Runs &middot; Most Active</div>
      </div>
      <div class="year-block">
        <div class="yr">2026</div>
        <div class="vers">Chrome 144&ndash;146</div>
        <div class="runs">3</div>
        <div class="runs-label">Runs (so far)</div>
      </div>
    </div>

    <div style="margin-top:24px;">
      <div id="infog-timeline-chart" class="infog-container" style="height:300px;"></div>
    </div>
  </section>

  <!-- ═══ METHODOLOGY MILESTONES ═══ -->
  <section class="infog-section">
    <div class="section-title">Methodology Milestones</div>
    <h2 style="font-size:24px;font-weight:700;letter-spacing:-0.02em;margin-bottom:12px;">Why Cross-Version Comparisons Are Dangerous</h2>

    <div class="callout-warn">
      <span class="icon">&#9888;&#65039;</span>
      <span class="msg">
        <strong>Chrome 118 (2023)</strong> marked the most significant methodology change &mdash;
        the overall score switched from arithmetic mean to <strong>weighted geometric mean</strong>,
        with concurrent CPU throttling recalibration. Comparisons across this boundary are unreliable.
      </span>
    </div>

    <div id="infog-methodology" class="infog-container" style="height:380px;"></div>
  </section>

  <!-- ═══ PLATFORM COVERAGE ═══ -->
  <section class="infog-section">
    <div class="section-title">Platform &amp; Framework Coverage</div>
    <h2 style="font-size:24px;font-weight:700;letter-spacing:-0.02em;margin-bottom:12px;">Coverage at a Glance</h2>

    <div class="coverage-grid">
      <div class="cov-card">
        <div class="cov-icon mac">&#127822;</div>
        <div class="cov-info">
          <div class="cov-label">Primary Platform</div>
          <div class="cov-pct" style="color:var(--blue);">macOS (OSX)</div>
          <div class="cov-detail">Over 95% of all benchmark runs &mdash; reflects macOS + Chrome performance characteristics</div>
        </div>
      </div>
      <div class="cov-card">
        <div class="cov-icon win">&#x1F4BB;</div>
        <div class="cov-info">
          <div class="cov-label">Secondary Platform</div>
          <div class="cov-pct" style="color:var(--orange);">Windows</div>
          <div class="cov-detail">Only 2 runs: Chrome 104 (2022) &amp; Chrome 121 (2024)</div>
        </div>
      </div>
    </div>

    <div style="margin-top:16px; padding: 14px 18px; background: var(--bg-secondary); border: 1px solid var(--border); border-radius: 8px; font-size: 13px; color: var(--text-secondary); line-height: 1.6;">
      <strong style="color: var(--teal);">Keyed-Only Alternation</strong> &mdash;
      Since Chrome 139 (2025), odd-numbered Chrome versions often benchmark <strong style="color:var(--text-primary);">keyed frameworks only</strong>,
      while even-numbered versions include both keyed and non-keyed implementations. This alternating pattern affects which data is available for any given Chrome release.
    </div>
  </section>

  <!-- ═══ KEY TAKEAWAYS ═══ -->
  <section class="infog-section" style="border-bottom: none;">
    <div class="section-title">Key Takeaways</div>
    <h2 style="font-size:24px;font-weight:700;letter-spacing:-0.02em;margin-bottom:4px;">For Developers</h2>
    <p style="font-size:14px;color:var(--text-secondary);margin-bottom:8px;">Actionable insights from 8 years of benchmark history.</p>
    <div id="infog-takeaways" class="infog-container" style="height:420px;"></div>
  </section>

  <!-- ═══ FOOTER ═══ -->
  <footer class="poster-footer">
    <span class="source">
      Source: <a href="https://github.com/krausest/js-framework-benchmark">github.com/krausest/js-framework-benchmark</a>
    </span>
    <span class="date">Data Report &middot; Generated May 2026</span>
  </footer>

</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
(function() {
  const containers = [
    {
      id: 'infog-timeline-chart',
      syntax: `infographic chart-bar-plain-text
data
  title Official Runs per Year
  values
    - label 2017-19
      value 4
    - label 2020
      value 5
    - label 2021
      value 9
    - label 2022
      value 13
    - label 2023
      value 12
    - label 2024
      value 12
    - label 2025
      value 12
    - label 2026
      value 3
theme
  palette #58a6ff #3fb950 #a371f7 #f78166 #d29922 #39d2c0 #8b949e #6e7681`
    },
    {
      id: 'infog-methodology',
      syntax: `infographic sequence-ascending-steps
data
  title Methodology Evolution
  desc Key changes since Chrome 118 (2023) that break cross-version comparisons
  sequences
    - label Weighted Geometric Mean
      desc Chrome 118 (2023): Overall score switched from arithmetic mean for more balanced ranking
    - label CPU Throttling Recalibrated
      desc Chrome 118 (2023): Throttling factors adjusted for realistic load simulation
    - label Measurement Fine-Tuning
      desc Chrome 118+ (2023–present): Ongoing refinements to timing and driver instrumentation
    - label Keyed-Only Alternation
      desc Chrome 139+ (2025–2026): Odd-numbered Chrome versions benchmark keyed frameworks only
  order asc
theme
  palette #58a6ff #d29922 #f78166 #a371f7`
    },
    {
      id: 'infog-takeaways',
      syntax: `infographic list-column-done-list
data
  title Key Takeaways for Developers
  desc Five rules for using the JS Framework Benchmark responsibly
  lists
    - label Compare within the same Chrome version
      desc Methodology and throttling differ across releases — cross-version results are misleading
    - label Consult the latest run for current standings
      desc Chrome 146 (macOS) reflects the most up-to-date framework performance data
    - label Know keyed vs non-keyed modes
      desc Recent odd-numbered Chrome runs benchmark keyed frameworks only; even runs include both
    - label 60+ data points over 8 years
      desc This is the longest-running, most comprehensive JS framework performance tracker available
    - label Weighted geometric mean since Chrome 118
      desc Provides a more balanced overall score than the previous arithmetic mean approach
theme
  palette #58a6ff #3fb950 #d29922 #f78166 #a371f7`
    }
  ];

  containers.forEach(function(c) {
    var el = document.getElementById(c.id);
