const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('file://' + require('path').resolve('/app/output/poster.html'), { waitUntil: 'networkidle' });
  await page.waitForSelector('#render-complete', { state: 'attached', timeout: 15000 });
  await page.waitForTimeout(1000);

  // Check SVG rendering
  const svgCount = await page.evaluate(() => document.querySelectorAll('svg').length);
  const infogContainers = await page.evaluate(() => {
    return Array.from(document.querySelectorAll('.infog-container')).map(el => ({
      id: el.id,
      hasSvg: el.querySelector('svg') !== null,
      childCount: el.children.length,
      innerHTML_length: el.innerHTML.length
    }));
  });

  console.log('SVG count:', svgCount);
  console.log('Infographic containers:', JSON.stringify(infogContainers, null, 2));

  // Check for errors on console
  page.on('console', msg => console.log('PAGE LOG:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await browser.close();
})();
