const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  await page.setViewportSize({ width: 1200, height: 900 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait for infographics to finish rendering
  await page.waitForSelector('#render-complete', { state: 'attached', timeout: 15000 });
  await page.waitForTimeout(1000);

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png'
  });

  console.log('Screenshot saved to /app/output/final_poster.png');
  await browser.close();
})().catch(err => {
  console.error('Render failed:', err);
  process.exit(1);
});

